using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Reflection;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class ServerProfilesTests {
  static Type type; static object store; static readonly JavaScriptSerializer json=new JavaScriptSerializer(); static int checks;
  static void Check(bool b,string name){if(!b)throw new Exception("FAIL "+name);checks++;}
  static object Call(string name,params object[] args){try{return type.GetMethod(name).Invoke(store,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static Dictionary<string,object> D(object o){return json.Deserialize<Dictionary<string,object>>(json.Serialize(o));}
  static Dictionary<string,object> Listing(){return D(Call("List"));}
  static object[] Rows(Dictionary<string,object> listing){return ((IEnumerable)listing["servers"]).Cast<object>().ToArray();}
  static Dictionary<string,object> Row(){return (Dictionary<string,object>)Rows(Listing())[0];}
  static Dictionary<string,object> Payload(string stamp){return new Dictionary<string,object>{{"stamp",stamp},{"id",""},{"name","Fixture"},{"host","127.0.0.1"},{"port",16261},{"queryPort",0},{"username","tester"},{"userPassword","role-secret-9284"},{"serverPassword","server-secret-4612"},{"useSteamRelay",false},{"description","Private note"}};}
  static void Reject(Action a,string n){bool refused=false;try{a();}catch{refused=true;}Check(refused,n);}
  static string Field(object o,string n){return (string)o.GetType().GetField(n).GetValue(o);}
  static byte[] Info(){var b=new List<byte>(new byte[]{255,255,255,255,73,17});foreach(string s in new[]{"Public\nServer","map","folder","Project Zomboid"})b.AddRange(Encoding.UTF8.GetBytes(s+"\0"));b.AddRange(new byte[]{56,166,3,24,0,100,119,0,1});b.AddRange(Encoding.UTF8.GetBytes("42.0\0"));return b.ToArray();}
  public static int Main(){string root=Path.Combine(LauncherTestPaths.Root,"orange-server-tests-"+Guid.NewGuid().ToString("N"));try{
   type=typeof(ServerProfilesTests).Assembly.GetType("PZ3D.ServerProfiles");Check(type!=null,"server profile store exists");store=Activator.CreateInstance(type,new object[]{root});
   foreach(string malformed in new[]{"","{}","{\"version\":1}","{\"servers\":[]}","{\"version\":\"1\",\"servers\":[]}","{\"version\":1,\"servers\":{}}","{\"version\":1,\"servers\":null}"}){Directory.CreateDirectory(root);string damaged=Path.Combine(root,"server-profiles.json");byte[] literal=Encoding.UTF8.GetBytes(malformed);File.WriteAllBytes(damaged,literal);Reject(()=>Call("List"),"incomplete existing store rejected: "+malformed);string damageStamp;using(var hash=System.Security.Cryptography.SHA256.Create())damageStamp=BitConverter.ToString(hash.ComputeHash(literal)).Replace("-","").ToLowerInvariant();Reject(()=>Call("Upsert",Payload(damageStamp)),"damaged existing store cannot be upserted");Check(File.ReadAllBytes(damaged).SequenceEqual(literal),"damaged store exact bytes preserved");File.Delete(damaged);}
   var empty=Listing();Check(Rows(empty).Length==0,"empty store lists no credentials");var p=Payload((string)empty["stamp"]);Call("Upsert",p);var row=Row();string id=(string)row["id"];Check(id.Length==32&&Guid.ParseExact(id,"N")!=Guid.Empty,"generated opaque ID");Check((bool)row["hasUserPassword"]&&(bool)row["hasServerPassword"],"two independent password flags");string output=json.Serialize(Listing());Check(!output.Contains("role-secret")&&!output.Contains("server-secret"),"list hides secret values");string disk=File.ReadAllText(Path.Combine(root,"server-profiles.json"));Check(!disk.Contains("role-secret")&&!disk.Contains("server-secret"),"persistent passwords encrypted");object target=Call("Target",id);Check(Field(target,"UserPassword")=="role-secret-9284"&&Field(target,"ServerPassword")=="server-secret-4612","DPAPI recovers both independent passwords");
   Reject(()=>Call("Upsert",p),"stale upsert refuses");p["stamp"]=Listing()["stamp"];p["id"]=id;p.Remove("userPassword");p["serverPassword"]="";Call("Upsert",p);target=Call("Target",id);Check(Field(target,"UserPassword")=="role-secret-9284"&&Field(target,"ServerPassword")=="","absent retains and explicit empty clears");
   foreach(string bad in new[]{"https://example.com","host/path","bad host","a..b","-invalid.example"}){p["host"]=bad;p["stamp"]=Listing()["stamp"];Reject(()=>Call("Upsert",p),"reject invalid host "+bad);}p["host"]="example.com";foreach(int bad in new[]{0,65536,-1}){p["port"]=bad;Reject(()=>Call("Upsert",p),"reject port bounds");}p["port"]=16261;
   var parse=type.GetMethod("ParseInfo",BindingFlags.Static|BindingFlags.NonPublic);Check(parse!=null,"public protocol parser available internally");var parsed=D(parse.Invoke(null,new object[]{Info(),id,12,"Private note"}));Check((string)parsed["status"]=="online"&&Convert.ToInt32(parsed["players"])==3&&Convert.ToInt32(parsed["maxPlayers"])==24,"literal A2S counts parsed");Check((string)parsed["name"]=="Public Server"&&(string)parsed["description"]=="Private note","sanitized public name with note fallback");foreach(byte[] bad in new[]{new byte[]{255,255,255,255,73},new byte[]{254,255,255,255,73},Info().Take(Info().Length-2).ToArray()}){var unknown=D(parse.Invoke(null,new object[]{bad,id,1,""}));Check((string)unknown["status"]=="unknown"&&unknown["players"]==null,"malformed or split remains unknown");}
   using(var udp=new UdpClient(new IPEndPoint(IPAddress.Loopback,0))){udp.Client.ReceiveTimeout=4000;int port=((IPEndPoint)udp.Client.LocalEndPoint).Port;Exception serverError=null;var thread=new Thread(()=>{try{IPEndPoint ep=null;var req=udp.Receive(ref ep);Check(req.SequenceEqual(new byte[]{255,255,255,255,84,83,111,117,114,99,101,32,69,110,103,105,110,101,32,81,117,101,114,121,0}),"query sends only public A2S request");byte[] challenge={255,255,255,255,65,1,2,3,4};udp.Send(challenge,challenge.Length,ep);var retry=udp.Receive(ref ep);Check(retry.Skip(retry.Length-4).SequenceEqual(new byte[]{1,2,3,4}),"query echoes challenge bytes");byte[] reply=Info();udp.Send(reply,reply.Length,ep);}catch(Exception e){serverError=e;}});thread.Start();p["stamp"]=Listing()["stamp"];p["queryPort"]=port;p["host"]="127.0.0.1";Call("Upsert",p);var query=D(Call("Query",id,CancellationToken.None));thread.Join();if(serverError!=null)throw serverError;Check((string)query["status"]=="online"&&Convert.ToInt32(query["players"])==3,"real loopback challenge query");Check(!json.Serialize(query).Contains("role-secret"),"query exposes no credential");}
   var cancelled=new CancellationToken(true);Check((string)D(Call("Query",id,cancelled))["status"]=="unknown","cancelled query remains unknown");
   using(var silent=new UdpClient(new IPEndPoint(IPAddress.Loopback,0))){p["stamp"]=Listing()["stamp"];p["queryPort"]=((IPEndPoint)silent.Client.LocalEndPoint).Port;Call("Upsert",p);var watch=System.Diagnostics.Stopwatch.StartNew();var timeout=D(Call("Query",id,CancellationToken.None));Check((string)timeout["status"]=="unknown"&&timeout["players"]==null,"silent responder does not fabricate offline or player count");Check(watch.ElapsedMilliseconds<3500,"UDP no-response deadline bounded");watch.Restart();Call("Query",id,CancellationToken.None);Check(watch.ElapsedMilliseconds<500,"query failure backoff uses cached result");}
   var savedStore=store;store=Activator.CreateInstance(type,new object[]{root});Check(Field(Call("Target",id),"UserPassword")=="role-secret-9284","reopened store decrypts persisted credential");p["stamp"]=Listing()["stamp"];p["description"]="Updated by other window";Call("Upsert",p);store=savedStore;Check((string)D(Call("Query",id,CancellationToken.None))["description"]=="Updated by other window","cache invalidates after another window edits profile");
   byte[] valid=File.ReadAllBytes(Path.Combine(root,"server-profiles.json"));File.WriteAllText(Path.Combine(root,"server-profiles.json"),"{broken");Reject(()=>Call("List"),"damaged store fails instead of becoming empty");Reject(()=>Call("Delete",id,(string)empty["stamp"]),"damaged store cannot overwrite existing data");Check(File.ReadAllText(Path.Combine(root,"server-profiles.json"))=="{broken","damaged store preserved");File.WriteAllBytes(Path.Combine(root,"server-profiles.json"),valid);
   Reject(()=>Call("Delete",id,(string)empty["stamp"]),"stale delete refuses");Call("Delete",id,(string)Listing()["stamp"]);Check(Rows(Listing()).Length==0,"delete removes own row");Reject(()=>Call("Target","../escape"),"opaque ID rejects traversal");Console.WriteLine("PASS ServerProfilesTests "+checks+" checks");return 0;
  }catch(Exception e){Console.WriteLine(e.Message);return 1;}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
 }
}
